import{_ as s,C as r,o as d,c as n,a2 as t,E as a}from"./chunks/framework.BxGh02fV.js";const f=JSON.parse('{"title":"Choisir son organisation","description":"","frontmatter":{"title":"Choisir son organisation"},"headers":[],"relativePath":"guide/setup.md","filePath":"guide/setup.md"}'),l={name:"guide/setup.md"};function i(u,e,c,p,m,h){const o=r("Ask");return d(),n("div",null,[e[0]||(e[0]=t('<h1 id="choisir-son-organisation" tabindex="-1">Choisir son organisation <a class="header-anchor" href="#choisir-son-organisation" aria-label="Permalink to &quot;Choisir son organisation&quot;">​</a></h1><p>Avant de créer ou de reprendre un projet, deux choix déterminent la façon dont Effortless travaille avec vous : <strong>comment l&#39;agent avance</strong> (le mode de travail) et <strong>où vit le code</strong> (l&#39;organisation en modules). Les deux se changent ensuite, mais bien les poser au départ évite des détours.</p><p>Un troisième point compte autant : <strong>où vous lancez votre agent</strong>. La meilleure expérience vient d&#39;un agent en ligne de commande ouvert à la racine du projet — voir <a href="/Effortless/agent/#travailler-au-mieux-l-agent-ouvert-a-la-racine-du-projet">Travailler au mieux</a>.</p><h2 id="le-mode-de-travail" tabindex="-1">Le mode de travail <a class="header-anchor" href="#le-mode-de-travail" aria-label="Permalink to &quot;Le mode de travail&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Mode</th><th>L&#39;agent</th><th>Le moteur</th><th>Pour qui</th></tr></thead><tbody><tr><td><strong>Full</strong></td><td>avance seul, sans validation intermédiaire</td><td>n&#39;empêche rien</td><td>vous connaissez Effortless et faites confiance à votre agent</td></tr><tr><td><strong>Semi-auto</strong></td><td>propose ; vous validez les jalons clés</td><td>désactive ses outils d&#39;exécution : livraison, regroupement du code, boucle autonome, boucle équipe</td><td>vous voulez garder la main sur ce qui s&#39;exécute</td></tr><tr><td><strong>Tutoré</strong></td><td>avance pas à pas, explique et fait confirmer chaque étape</td><td>n&#39;empêche rien : c&#39;est une consigne pour l&#39;agent</td><td>vous découvrez Effortless ou la méthode OPALE</td></tr></tbody></table><p>Un projet créé ou repris démarre en <strong>Full</strong>. Le mode se change à tout moment dans les <a href="/Effortless/guide/settings.html">Réglages du projet</a>, ou par l&#39;agent avec <code>effortless_mode_set</code>.</p><div class="warning custom-block"><p class="custom-block-title">Semi-auto et reprise</p><p>En semi-auto, l&#39;étape <strong>Regrouper le code</strong> de la <a href="/Effortless/guide/adopt.html">reprise d&#39;un projet existant</a> est refusée : elle déplace des fichiers. Faites la reprise en Full ou en Tutoré, puis passez en semi-auto.</p></div><h2 id="l-organisation-du-code" tabindex="-1">L&#39;organisation du code <a class="header-anchor" href="#l-organisation-du-code" aria-label="Permalink to &quot;L&#39;organisation du code&quot;">​</a></h2><p>Effortless sépare le <strong>pilotage</strong> du <strong>code</strong>. Le pilotage (<code>effortless.json</code>, <code>.effortless/</code>, <code>blueprints/</code>) vit toujours à la racine du projet. Le code se déclare en <strong>modules</strong> (des « stacks ») : chacun a un identifiant, un emplacement, ses langages et ses normes de développement. L&#39;écran <a href="/Effortless/guide/modules.html">Modules</a> les montre tous.</p><h3 id="un-seul-depot-le-code-a-la-racine" tabindex="-1">Un seul dépôt, le code à la racine <a class="header-anchor" href="#un-seul-depot-le-code-a-la-racine" aria-label="Permalink to &quot;Un seul dépôt, le code à la racine&quot;">​</a></h3><p>Le cas le plus simple. Sans déclaration, le projet a un module implicite, <code>default</code>, qui couvre la racine. Rien à faire.</p><h3 id="plusieurs-modules-dans-le-projet" tabindex="-1">Plusieurs modules dans le projet <a class="header-anchor" href="#plusieurs-modules-dans-le-projet" aria-label="Permalink to &quot;Plusieurs modules dans le projet&quot;">​</a></h3><p>Un dépôt unique qui porte plusieurs parties — une application, une API, une documentation. Chaque module vit dans <code>codebase/&lt;module&gt;/</code>. Vous le déclarez depuis l&#39;<a href="/Effortless/guide/create.html">assistant de création</a> (étape Stack), depuis <strong>Préférences › Modèle de stack</strong>, ou par l&#39;agent avec <code>effortless_stack_add</code>. La <a href="/Effortless/guide/adopt.html">reprise d&#39;un projet existant</a> range le code de la racine dans <code>codebase/&lt;module&gt;/</code>.</p><h3 id="un-module-externe-avec-son-propre-depot" tabindex="-1">Un module externe, avec son propre dépôt <a class="header-anchor" href="#un-module-externe-avec-son-propre-depot" aria-label="Permalink to &quot;Un module externe, avec son propre dépôt&quot;">​</a></h3><p>Le code d&#39;un module vit hors du projet, dans un autre dépôt git que vous développez aussi. Déclarez-le avec son chemin et <code>git: true</code> :</p>',15)),a(o,{say:"Déclare le module api, dont le code est dans ../facturation-api, avec son propre dépôt git.",verb:"effortless_stack_add",family:"stacks",args:'{"id":"api","path":"../facturation-api","git":true}'}),e[1]||(e[1]=t('<p>Effortless suit alors ce dépôt comme celui du projet : la <a href="/Effortless/guide/drift.html">dérive</a> y est lue, et le hook anti-dérive y est posé aussi quand vous l&#39;installez.</p><h3 id="des-sources-partagees-en-marge" tabindex="-1">Des sources partagées, en marge <a class="header-anchor" href="#des-sources-partagees-en-marge" aria-label="Permalink to &quot;Des sources partagées, en marge&quot;">​</a></h3><p>Le code d&#39;un module vit dans un dépôt que vous <strong>partagez</strong> — une bibliothèque commune à plusieurs de vos projets, un dépôt tiers — et que vous ne voulez pas instrumenter. Déclarez-le avec son chemin, <strong>sans</strong> <code>git: true</code> :</p>',3)),a(o,{say:"Déclare le module socle, dont le code partagé est dans ../socle-commun, sans le suivre.",verb:"effortless_stack_add",family:"stacks",args:'{"id":"socle","path":"../socle-commun"}'}),e[2]||(e[2]=t('<p>Effortless travaille alors en marge de ces sources : il n&#39;y pose aucun hook et n&#39;y commite rien. En contrepartie, la dérive n&#39;y est pas surveillée. <code>effortless_stack_list</code> marque ce module <strong>NON SUIVIE</strong> : c&#39;est voulu, l&#39;étiquette rappelle simplement ce choix.</p><h2 id="le-hook-anti-derive-quand-et-ou" tabindex="-1">Le hook anti-dérive : quand, et où <a class="header-anchor" href="#le-hook-anti-derive-quand-et-ou" aria-label="Permalink to &quot;Le hook anti-dérive : quand, et où&quot;">​</a></h2><p>Le hook pre-commit anti-dérive refuse un commit de code quand aucune tâche n&#39;est en cours. Il n&#39;est <strong>jamais posé d&#39;office</strong> : ni à la création, ni à la reprise.</p><ul><li>Vous l&#39;installez depuis l&#39;écran <a href="/Effortless/guide/drift.html">Dérive</a> (<strong>Installer le hook pre-commit</strong>) ou par l&#39;agent avec <code>effortless_drift_hook_install</code>.</li><li>Il est posé sur le dépôt du projet, et sur chaque module déclaré avec <code>git: true</code>.</li><li>Il n&#39;est jamais posé sur des sources partagées (un module externe sans <code>git: true</code>).</li><li>Il ne remplace jamais un hook pre-commit qui n&#39;est pas d&#39;Effortless : l&#39;installation est refusée, et le refus nomme le fichier.</li></ul><h2 id="quel-choix-pour-quel-cas" tabindex="-1">Quel choix pour quel cas <a class="header-anchor" href="#quel-choix-pour-quel-cas" aria-label="Permalink to &quot;Quel choix pour quel cas&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Votre situation</th><th>Mode</th><th>Organisation</th></tr></thead><tbody><tr><td>Vous découvrez Effortless sur un petit projet</td><td>Tutoré</td><td>un seul dépôt</td></tr><tr><td>Vous voulez valider ce qui s&#39;exécute</td><td>Semi-auto</td><td>selon le projet</td></tr><tr><td>Un dépôt avec une application, une API, une documentation</td><td>Full ou Semi-auto</td><td>modules dans <code>codebase/</code></td></tr><tr><td>Le code est réparti dans plusieurs dépôts que vous développez</td><td>Full ou Semi-auto</td><td>modules externes avec <code>git: true</code></td></tr><tr><td>Vous vous appuyez sur une bibliothèque commune que vous ne devez pas modifier ni instrumenter</td><td>au choix</td><td>sources partagées (sans <code>git: true</code>)</td></tr><tr><td>Un dépôt existant dont la structure doit rester telle quelle</td><td>au choix</td><td>créez le projet sans reprise, puis déclarez les modules là où ils sont, avec <code>path</code></td></tr></tbody></table>',6))])}const v=s(l,[["render",i]]);export{f as __pageData,v as default};
